/* cppi::4fe4cea2574536bc97746224b1d72e437fcc8e8e8e9c54ad597311678e339876 */
SELECT cppib_sec_id, rating_value FROM performance.cppib_security_rating
                WHERE business_date = '2025-05-28' AND rating_agency = 'CPPIB'

/* cppi::e53fcdcbd10a1259719daf68156af57edd5a816908541a05ea5fe2e0fd84167f */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-06-12' and end_date = '2025-06-12')
and start_date = '2025-06-12' and end_date = '2025-06-12'

